"""NUL-safe file indexing for the stick backup task."""
import os, subprocess, sys, json

def find_index(root, maxdepth=None, include_hidden=True):
    """Return {relpath: size} for all regular files under root (NUL-safe)."""
    args = ["find", root, "-type", "f", "-printf", "%s\0%P\0"]
    if maxdepth is not None:
        args = ["find", root, "-maxdepth", str(maxdepth), "-type", "f", "-printf", "%s\0%P\0"]
    p = subprocess.run(args, capture_output=True)
    if p.returncode != 0:
        raise RuntimeError(f"find failed on {root}: {p.stderr.decode()[:500]}")
    items = p.stdout.split(b'\0')
    if items and items[-1] == b'':
        items.pop()
    assert len(items) % 2 == 0, f"odd item count for {root}: {len(items)}"
    idx = {}
    dups = 0
    for i in range(0, len(items), 2):
        size = int(items[i])
        path = items[i+1].decode('utf-8')
        if path in idx:
            dups += 1
        idx[path] = size
    return idx, dups

def match(stick_idx, disk_idx, rel_map_prefix=""):
    """Classify stick files: SAME / SIZE_MISMATCH / MISSING.
    rel_map_prefix: stick relpath -> disk relpath via simple concatenation handled by caller.
    Returns (same, size_mismatch[(stick_rel, s_size, d_size)], missing[(stick_rel, size)]).
    """
    same = []
    sm = []
    missing = []
    for rel, size in stick_idx.items():
        if rel in disk_idx:
            if disk_idx[rel] == size:
                same.append(rel)
            else:
                sm.append((rel, size, disk_idx[rel]))
        else:
            missing.append((rel, size))
    return same, sm, missing

